package net.minecraft.server.level; import java.util.UUID; import net.minecraft.network.chat.Component; import net.minecraft.server.MinecraftServer; public class ServerPlayer {public UUID id=UUID.randomUUID(); public String name="Tester"; public int deaths=0;public int actionbars=0; public String lastActionbar=""; public UUID getUUID(){return id;} public Component getName(){return Component.literal(name);} public FakeLevel level(){return new FakeLevel();} public Stats getStats(){return new Stats(this);} public void displayClientMessage(Component c,boolean actionbar){this.actionbars++;this.lastActionbar=c.toString();} public static class FakeLevel{public Dimension dimension(){return new Dimension();}} public static class Dimension{public Location location(){return new Location();}} public static class Location{public String toString(){return "minecraft:overworld";}} public static class Stats{ServerPlayer p;public Stats(ServerPlayer p){this.p=p;}public int getValue(String stat){return p.deaths;}}}